/**
 * Offline preview mode.
 * Loads a frozen, read-only snapshot (generated by `npm run snapshot`) and answers
 * GET requests locally so the dashboard, review queue, analytics and reports stay
 * explorable while the API is down. Mutations are rejected with a clear message.
 *
 * The snapshot is imported dynamically, so it is a separate lazy chunk and costs
 * nothing on a normal online load.
 */

let snapshot = null;
let loading = null;

export async function enableOffline() {
  if (snapshot) return snapshot;
  if (!loading) {
    loading = import('./offline/snapshot.json').then((mod) => {
      snapshot = mod.default || mod;
      return snapshot;
    });
  }
  return loading;
}

export function disableOffline() {
  snapshot = null;
  loading = null;
}

export function offlineMeta() {
  return snapshot?.__meta || null;
}

export function getSnapshot() {
  return snapshot;
}

const match = (pathname, pattern) => {
  const m = pathname.match(pattern);
  return m ? decodeURIComponent(m[1]) : null;
};

/** Returns the frozen payload for a GET URL, or throws when it is not covered. */
export function offlineResponder(url) {
  if (!snapshot) throw new Error('Offline snapshot is not loaded yet.');

  const { pathname, searchParams } = new URL(url, window.location.origin);
  const s = snapshot;

  if (pathname === '/api/bootstrap') {
    const id = searchParams.get('studentId') || 'aziz';
    const person = s.bootstrap.roster.find((r) => r.id === id);
    return { ...s.bootstrap, viewer: person ? { id: person.id, name: person.name, role: 'student', avatar: person.avatar, coins: person.coins } : s.bootstrap.viewer };
  }

  if (pathname === '/api/teacher/overview') return s.teacherOverview;
  if (pathname === '/api/teacher/heatmap') return s.heatmap;
  if (pathname === '/api/teacher/sets') return s.sets;
  if (pathname === '/api/leaderboard') return s.leaderboard;
  if (pathname === '/api/parents') return { parents: s.parents };
  if (pathname === '/api/parents/telegram-log') return { log: [] };
  if (pathname === '/api/prompts') return s.prompts;
  if (pathname === '/api/audit') return { audit: s.audit };

  const studentId = match(pathname, /^\/api\/student\/([^/]+)$/);
  if (studentId) {
    const payload = s.students[studentId];
    if (!payload) throw new Error(`No offline snapshot for student ${studentId}.`);
    return payload;
  }

  const rewardId = match(pathname, /^\/api\/rewards\/([^/]+)$/);
  if (rewardId) {
    const payload = s.rewards[rewardId];
    if (!payload) throw new Error(`No offline reward data for ${rewardId}.`);
    return payload;
  }

  const submissionId = match(pathname, /^\/api\/teacher\/submissions\/([^/]+)$/);
  if (submissionId) {
    const submission = s.teacherOverview.queue.find((x) => x.id === submissionId);
    if (!submission) throw new Error(`Submission ${submissionId} is not in the offline snapshot.`);
    const variant = (s.sets.sets || []).flatMap((set) => set.variants || []).find((v) => v.code === submission.variantCode) || null;
    return { submission, variant, tutorLog: [], peers: [] };
  }

  const parentId = match(pathname, /^\/api\/parents\/([^/]+)\/report$/);
  if (parentId) {
    const report = s.parentReports[parentId];
    if (!report) throw new Error(`No offline report for ${parentId}.`);
    return report;
  }

  const mentor = pathname === '/api/mentor/state';
  if (mentor) {
    const id = searchParams.get('studentId') || 'aziz';
    return {
      active: false,
      turn: 0,
      correct: 0,
      asked: 0,
      coinsEarned: 0,
      streak: 0,
      history: [],
      voiceprintEnrolled: !!s.students[id]?.student?.voiceprintEnrolled,
      offline: true,
    };
  }

  throw new Error(`No offline snapshot for ${pathname}.`);
}
